#include <stdio.h>
#include <unistd.h>
#include <CoreGraphics/CoreGraphics.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("Usage: %s <x> <y>\n", argv[0]);
        return 1;
    }

    float x = atof(argv[1]);
    float y = atof(argv[2]);

    printf("Attempting to send tap event at (%.1f, %.1f)\n", x, y);

    // Create and post a mouse down event at the specified location
    CGEventRef mouseDown = CGEventCreateMouseEvent(
        NULL,
        kCGEventLeftMouseDown,
        CGPointMake(x, y),
        kCGMouseButtonLeft
    );

    CGEventPost(kCGHIDEventTap, mouseDown);
    CFRelease(mouseDown);

    // Create and post a mouse up event
    usleep(50000); // Wait 50ms

    CGEventRef mouseUp = CGEventCreateMouseEvent(
        NULL,
        kCGEventLeftMouseUp,
        CGPointMake(x, y),
        kCGMouseButtonLeft
    );

    CGEventPost(kCGHIDEventTap, mouseUp);
    CFRelease(mouseUp);

    printf("Tap event sent\n");
    return 0;
}
EOF

