#include <stdio.h>
#include <unistd.h>
#include <CoreGraphics/CoreGraphics.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <key_code> [modifiers]\n", argv[0]);
        printf("Example: %s 3  (sends Cmd+F for search)\n", argv[0]);
        return 1;
    }

    int keyCode = atoi(argv[1]);
    CGEventFlags flags = kCGEventFlagMaskCommand;  // Cmd key by default

    if (argc >= 3) {
        flags = atoi(argv[2]);
    }

    printf("Sending key code %d with flags %llu\n", keyCode, flags);

    // Create and post key down event
    CGEventRef keyDown = CGEventCreateKeyboardEvent(NULL, keyCode, true);
    CGEventSetFlags(keyDown, flags);
    CGEventPost(kCGHIDEventTap, keyDown);
    CFRelease(keyDown);

    usleep(50000);  // 50ms delay

    // Create and post key up event
    CGEventRef keyUp = CGEventCreateKeyboardEvent(NULL, keyCode, false);
    CGEventSetFlags(keyUp, flags);
    CGEventPost(kCGHIDEventTap, keyUp);
    CFRelease(keyUp);

    printf("Key event sent\n");
    return 0;
}
EOF

