            CGPointMake(x, y),
            kCGMouseButtonLeft
        );
        CGEventPost(kCGHIDEventTap, mouseUp);
        CFRelease(mouseUp);

        if (i == 0) {
            usleep(100000);  // Delay between taps
        }
    }
}

